    /**
     * Tests getting all RecordsRepositorys.
     *
     * @return    Collection
     */
    public List<RecordsRepository> testGetAll() throws Throwable {
    LOGGER.info( "RecordsRepositoryTest:testGetAll() - Retrieving Collection of RecordsRepositorys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all RecordsRepository : " );
    List<RecordsRepository> collection  = null;

    try {
        // call the static get method on the RecordsRepositoryService
        collection = service.getAllRecordsRepository();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            RecordsRepository currEntity  = null;
            Iterator<RecordsRepository> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRecordsRepositoryId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

